{
  "county_id": "HVA11",
  "actions": [
    {
      "action_id": "timed-pathways",
      "action": "Adopt national cancer-specific pathways with maximum times per step and a single fast-track referral from primary care, following the Danish and Swedish model.",
      "rationale": "The optimiser picked timed-pathways for South Karelia wellbeing services county at an assumed cost of 186357 EUR per year, with a model scenario of 6 deaths postponed per year (range 0.9-12) and the action stayed in the portfolio in 89% of sensitivity runs.",
      "owner_role": "Wellbeing services county, coordinated nationally by FICAN",
      "indicator": "Patients waiting over 6 months during the year for access to specialised health care per 10 000 inhabitants",
      "roadmap_measure": "3.1.2"
    },
    {
      "action_id": "self-sampling",
      "action": "Mail a self-sampling kit with the second reminder to everyone who has not attended.",
      "rationale": "Cervical screening participation in South Karelia wellbeing services county is 74.1% against the 80% target, and the model scenario expects self-sampling to add 1.5-4.5 percentage points, closing about 51% of the gap, at an assumed cost of 74543 EUR per year.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of women invited to cervical cancer screening (smear test) who attended, %",
      "roadmap_measure": "2.4.4"
    },
    {
      "action_id": "screening-reminders",
      "action": "Send a second kit with plain-language, multilingual instructions to non-responders; measure the gain as a stepped pilot.",
      "rationale": "Colorectal screening participation in South Karelia wellbeing services county is 75.7% against the 80% target, and the model scenario expects reminders to add 1.5-4.27 percentage points, closing about 70% of the gap, at an assumed cost of 49695 EUR per year.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of invited to colorectal cancer screening who attended, %",
      "roadmap_measure": "1.3.1"
    }
  ],
  "evidence_does_not_support": "The evidence does not support that these actions will guarantee the modelled deaths postponed or participation gains, because the Danish pathway evidence is before/after without a control group, the Finnish self-sampling gain is far smaller than the international pooled estimate, and no Finnish effect size exists for colorectal screening reminders."
}

